function validate([s, queries]) {
  if (s.length < 3 || s.length > 100000) return 's needs 3 to 10^5 characters.';
  if (!/^[*|]+$/.test(s)) return "s may contain only '*' and '|'.";
  if (queries.length < 1) return 'Give at least one query.';
  for (const q of queries) {
    if (q.length !== 2) return 'Each query is a pair [left, right].';
    if (!(q[0] >= 0 && q[0] <= q[1] && q[1] < s.length)) return 'Each query needs 0 <= left <= right < s.length.';
  }
  return null;
}

