function platesBetweenCandles(s, queries) {
  const n = s.length;
  const platesBefore = new Array(n + 1).fill(0);
  const prevCandle = new Array(n).fill(-1);
  const nextCandle = new Array(n).fill(n);

  for (let i = 0; i < n; i++) {
    platesBefore[i + 1] = platesBefore[i] + (s[i] === '*' ? 1 : 0);
    if (s[i] === '|') {
      prevCandle[i] = i;
    } else if (i > 0) {
      prevCandle[i] = prevCandle[i - 1];
    }
  }
  for (let i = n - 1; i >= 0; i--) {
    if (s[i] === '|') {
      nextCandle[i] = i;
    } else if (i < n - 1) {
      nextCandle[i] = nextCandle[i + 1];
    }
  }

  const answer = [];
  for (const [left, right] of queries) {
    const first = nextCandle[left];
    const last = prevCandle[right];
    if (first < last) {
      answer.push(platesBefore[last] - platesBefore[first]);
    } else {
      answer.push(0);
    }
  }
  return answer;
}

