function platesBetweenCandles(s, queries) {
  return queries.map(([left, right]) => {
    const piece = s.slice(left, right + 1);
    const a = piece.indexOf('|');
    const b = piece.lastIndexOf('|');
    if (a === -1 || a === b) return 0;
    let count = 0;
    for (const ch of piece.slice(a, b)) if (ch === '*') count++;
    return count;
  });
}

