function generate(rand, size) {
  const n = size === 'large' ? 10000 : 3 + Math.floor(rand() * 12);
  const candleChance = size === 'large' ? 0.05 + rand() * 0.3 : [0, 0.15, 0.4, 0.7, 1][Math.floor(rand() * 5)];
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < candleChance ? '|' : '*';
  const count = size === 'large' ? 2000 : 1 + Math.floor(rand() * 6);
  const queries = [];
  for (let q = 0; q < count; q++) {
    const a = Math.floor(rand() * n);
    const b = Math.floor(rand() * n);
    queries.push([Math.min(a, b), Math.max(a, b)]);
  }
  return [s, queries];
}
